pipeline {
    agent any
    stages {
        stage('Build') {
            steps {
                echo "Building #${env.BUILD_NUMBER}"   // Groovy fills in the build number
                sh '''
                    mkdir -p out
                    echo "built at $(date -u)" > out/info.txt
                '''
            }
        }
        stage('Test') {
            steps {
                sh 'test -s out/info.txt && echo OK'      // OK
            }
        }
    }
}

// Jenkinsfile at the top of the repository
pipeline {
    agent any
    triggers {
        pollSCM('H/5 * * * *')        // only if webhooks are impossible
    }
    stages {
        stage('Info') {
            steps {
                sh 'echo "commit $GIT_COMMIT on $GIT_BRANCH"'
                // commit 1a2b3c4d... on origin/main
                sh 'ls'                // the repository is already checked out
            }
        }
        stage('Build') {
            steps { sh 'make build' }
        }
    }
}

pipeline {
    agent any
    stages {
        stage('Test') {
            steps { sh './gradlew test' }
            post {
                always { junit 'build/test-results/test/*.xml' }
            }
        }
        stage('Package') {
            steps { sh './gradlew assemble' }
        }
    }
    post {
        success { archiveArtifacts artifacts: 'build/libs/*.jar', fingerprint: true }
        failure { echo "Build ${env.BUILD_NUMBER} failed: ${env.BUILD_URL}" }
        fixed   { echo 'Back to green' }
        cleanup { deleteDir() }       // wipe the workspace last
    }
}

pipeline {
    agent any
    environment {
        APP = 'shop'
        REGISTRY = credentials('registry-login')   // also sets REGISTRY_USR / REGISTRY_PSW
    }
    stages {
        stage('Publish') {
            steps {
                // single quotes: the shell replaces the secret, not Groovy
                sh 'echo "$REGISTRY_PSW" | docker login -u "$REGISTRY_USR" --password-stdin registry.example.com'
                withCredentials([string(credentialsId: 'slack-token', variable: 'SLACK')]) {
                    sh 'curl -sf -H "Authorization: Bearer $SLACK" https://slack.example/api'
                }
                echo "Published ${APP}"          // fine: not a secret
            }
        }
    }
}

pipeline {
    agent none
    stages {
        stage('Backend') {
            agent { docker { image 'maven:3.9-eclipse-temurin-21' } }
            steps { sh 'mvn -B -q verify' }
        }
        stage('Frontend') {
            agent { docker { image 'node:22-alpine'; args '-e CI=true' } }
            steps { sh 'npm ci && npm test' }
        }
        stage('Windows smoke test') {
            agent { label 'windows' }
            steps { bat 'run-smoke.cmd' }
        }
    }
}

pipeline {
    agent any
    options {
        timeout(time: 30, unit: 'MINUTES')
        buildDiscarder(logRotator(numToKeepStr: '30'))
        disableConcurrentBuilds()
    }
    parameters {
        choice(name: 'TARGET', choices: ['staging', 'production'])
        booleanParam(name: 'RUN_E2E', defaultValue: false)
    }
    triggers { cron('H 2 * * 1-5') }        // nightly on weekdays
    stages {
        stage('Build') { steps { sh 'make' } }
        stage('E2E') {                        // end-to-end tests of the whole system
            when { expression { params.RUN_E2E } }
            steps { sh 'make e2e' }
        }
        stage('Deploy') {
            when { allOf { branch 'main'; expression { params.TARGET == 'production' } } }
            steps { sh "./deploy.sh ${params.TARGET}" }
        }
    }
}

// One Jenkinsfile, different behaviour per kind of branch
pipeline {
    agent any
    stages {
        stage('Test') {
            steps { sh 'make test' }
        }
        stage('PR info') {
            when { changeRequest() }
            steps { echo "PR ${env.CHANGE_ID} into ${env.CHANGE_TARGET}" }
            // PR 42 into main
        }
        stage('Deploy') {
            when { branch 'main' }
            steps { sh './deploy.sh' }
        }
    }
}

pipeline {
    agent none
    stages {
        stage('Checks') {
            failFast true
            parallel {
                stage('Lint') { agent any; steps { sh 'make lint' } }
                stage('Unit') { agent any; steps { sh 'make unit' } }
            }
        }
        stage('Compat') {
            matrix {
                agent { label "${PLATFORM}" }
                axes {
                    axis { name 'PLATFORM'; values 'linux', 'windows' }
                    axis { name 'JDK'; values '17', '21' }
                }
                excludes { exclude { axis { name 'PLATFORM'; values 'windows' }; axis { name 'JDK'; values '17' } } }
                stages { stage('Test') { steps { echo "Testing ${PLATFORM} JDK ${JDK}" } } }
            }
        }
    }
}

// ci-lib repository: vars/standardPipeline.groovy
def call(Map cfg = [:]) {
    pipeline {
        agent { docker { image "${cfg.image ?: 'maven:3.9-eclipse-temurin-21'}" } }
        stages {
            stage('Build') { steps { sh 'mvn -B verify' } }
            stage('Deploy') {
                when { expression { cfg.deploy && env.BRANCH_NAME == 'main' } }
                steps { sh "./deploy.sh ${cfg.app}" }
            }
        }
        post { always { junit allowEmptyResults: true, testResults: 'target/surefire-reports/*.xml' } }
    }
}

// Application repository: Jenkinsfile (the whole file)
@Library('ci-lib@v2.1') _
standardPipeline(app: 'shop', deploy: true)

concepts.body:
Before declarative syntax existed, pipelines were written as **scripted pipelines**: plain Groovy built from steps like `node`, `stage`, `checkout scm` and `parallel`. There's no fixed structure, no `post` and no `when`; you use `try/catch/finally` (Groovy's way of handling errors) and `if` instead.

```groovy
node('linux') {
    stage('Build') { checkout scm; sh 'make' }
}
```

`node` takes an executor and a workspace; everything inside the block runs there.

A declarative pipeline can drop into Groovy with `script { }` inside `steps`. Use it for small logic: reading a file with `readFile`, looping to build the list of parallel branches, or setting a variable for later stages. If `script` blocks grow large, move the logic into a shared library.

Pipeline Groovy is **not normal Groovy**. Scripts run in the Groovy sandbox: a call that isn't on the allowed list fails with `RejectedAccessException` until an administrator approves it under **In-process Script Approval**.

The code is also rewritten so that a build can survive a restart (the next lesson). Because of that, a few Groovy features behave differently or fail, for example `sort` given a comparison closure (a small inline function). Steps like `readJSON`, `readYaml` and `writeFile` (Pipeline Utility Steps plugin) are safer than calling Java's own code directly.

