pipeline {
    agent any
    stages {
        stage('Dynamic tests') {
            steps {
                script {
                    def suites = ['api', 'web', 'worker']
                    def branches = [:]                      // an empty map
                    for (s in suites) {
                        def suite = s                       // copy per loop round
                        branches[suite] = { sh "make test-${suite}" }
                    }
                    parallel branches                       // 3 parallel branches
                    env.TESTED = suites.join(',')
                }
                echo "Tested: ${env.TESTED}"               // Tested: api,web,worker
            }
        }
    }
}

// Problem: a Matcher isn't serializable and would live across a step
// def m = (version =~ /(\d+)\.(\d+)/); sh 'make'; echo m[0][1]  -> NotSerializableException

@NonCPS
def parseMajor(String version) {
    def m = version =~ /(\d+)\.(\d+)/
    return m ? m[0][1] : null          // plain Groovy; no pipeline steps allowed here
}

pipeline {
    agent any
    options { durabilityHint('PERFORMANCE_OPTIMIZED') }
    stages {
        stage('Version') {
            steps {
                script {
                    def major = parseMajor(readFile('VERSION').trim())
                    echo "Major version ${major}"   // Major version 3
                }
                sh './ci/build-and-test.sh'          // one step, real work on the agent
            }
        }
    }
}
